#include <iostream>
#include <vector>
#include <string>
int main(int argc, char** argv) {
    std::vector<std::string> args(argv, argv + argc);
    // Print each argument with its index
    for (size_t i = 0; i < args.size(); i++) {
        std::cout << "arg[" << i << "] = "
                  << args[i] << "\n";
    }
    return 0;
}

def process_images(paths, size=(800, 600)):
    """Resize a batch with bilinear interpolation."""
    results = []
    for p in paths:
        img = load_image(p)
        if img is None:
            continue
        img = resize(img, size)
        results.append(img)
    return results

function fibonacci(n) {
    if (n <= 1) return n;
    return fibonacci(n - 1) + fibonacci(n - 2);
}
